type Read<T> =
  | { ok: true; value: T }
  | { ok: false; reason: "refused" | "truncated" | "invalid"; detail: string };
type Part = { type: string; text?: string; refusal?: string };

function parseAndValidate(parts: Part[], textType: string): Read<unknown> {
  const texts = parts.filter((p) => p.type === textType);
  // This extraction contract expects exactly one schema document, not several messages.
  if (texts.length !== 1 || typeof texts[0].text !== "string" || !texts[0].text.trim())
    return { ok: false, reason: "invalid", detail: "Expected one non-empty JSON text block." };
  try {
    const value = JSON.parse(texts[0].text);
    return { ok: true, value: Ticket.parse(value) }; // full local schema, including extra-key rejection
  } catch {
    return { ok: false, reason: "invalid", detail: "Malformed JSON or local schema violation." };
  }
}

function readClaude(msg: { stop_reason: string | null; content: Part[] }): Read<unknown> {
  if (msg.stop_reason === "refusal") return { ok: false, reason: "refused", detail: "Safety refusal." };
  if (msg.stop_reason === "max_tokens") return { ok: false, reason: "truncated", detail: "Token limit reached." };
  if (msg.stop_reason !== "end_turn") return { ok: false, reason: "invalid", detail: "Extraction did not finish normally." };
  return parseAndValidate(msg.content, "text");
}

function readResponses(r: { status: string; incomplete_details?: { reason?: string }; output: { type: string; content?: Part[] }[] }): Read<unknown> {
  const parts = r.output.filter((i) => i.type === "message").flatMap((i) => i.content ?? []);
  if (parts.some((p) => p.type === "refusal")) return { ok: false, reason: "refused", detail: "Safety refusal." };
  if (r.status === "incomplete") return { ok: false, reason: "truncated", detail: r.incomplete_details?.reason ?? "Incomplete response." };
  if (r.status !== "completed") return { ok: false, reason: "invalid", detail: "Response is not completed." };
  return parseAndValidate(parts, "output_text");
}

